Here is the commit message:
can: usb: etas_es58x: correctly anchor the urb in the read
 bulk callback

When submitting an urb, that is using the anchor pattern, it needs to be
anchored before submitting it otherwise it could be leaked if
usb_kill_anchored_urbs() is called.  This logic is correctly done
elsewhere in the driver, except in the read bulk callback so do that
here also.

Cc: Vincent Mailhol <mailhol@kernel.org>
Cc: Marc Kleine-Budde <mkl@pengutronix.de>
Cc: stable@kernel.org
Assisted-by: gkh_clanker_2000
Signed-off-by: Greg Kroah-Hartman <gregkh@linuxfoundation.org>
Reviewed-by: Vincent Mailhol <mailhol@kernel.org>
Tested-by: Vincent Mailhol <mailhol@kernel.org>
Link: https://patch.msgid.link/2026022320-poser-stiffly-9d84@gregkh
Fixes: 8537257874e9 ("can: etas_es58x: add core support for ETAS ES58X CAN USB interfaces")
Signed-off-by: Marc Kleine-Budde <mkl@pengutronix.de>

Here is the root cause:
The URB was not anchored before being submitted in the read bulk callback, so if usb_kill_anchored_urbs() was called (e.g., during device removal), the URB could not be found and killed, causing a memory leak or use-after-free.

Here is the patch:
  */
 static void es58x_read_bulk_callback(struct urb *urb)
 {
 	struct es58x_device *es58x_dev = urb->context;
 	const struct device *dev = es58x_dev->dev;
 	int i, ret;

 	switch (urb->status) {
 	case 0:		/* success */
 		break;

 	case -EOVERFLOW:
 		dev_err_ratelimited(dev, "%s: error %pe\n",
 				    __func__, ERR_PTR(urb->status));
 		es58x_print_hex_dump_debug(urb->transfer_buffer,
 					   urb->transfer_buffer_length);
 		goto resubmit_urb;

 	case -EPROTO:
 		dev_warn_ratelimited(dev, "%s: error %pe. Device unplugged?\n",
 				     __func__, ERR_PTR(urb->status));
 		goto free_urb;

 	case -ENOENT:
 	case -EPIPE:
 		dev_err_ratelimited(dev, "%s: error %pe\n",
 				    __func__, ERR_PTR(urb->status));
 		goto free_urb;

 	case -ESHUTDOWN:
 		dev_dbg_ratelimited(dev, "%s: error %pe\n",
 				    __func__, ERR_PTR(urb->status));
 		goto free_urb;

 	default:
 		dev_err_ratelimited(dev, "%s: error %pe\n",
 				    __func__, ERR_PTR(urb->status));
 		goto resubmit_urb;
 	}

 	ret = es58x_split_urb(es58x_dev, urb);
 	if ((ret != -ENODATA) && ret < 0) {
 		dev_err(es58x_dev->dev, "es58x_split_urb() returned error %pe",
 			ERR_PTR(ret));
 		es58x_print_hex_dump_debug(urb->transfer_buffer,
 					   urb->actual_length);

 		/* Because the urb command could not be parsed,
 		 * channel_id is not confirmed. Incrementing rx_errors
 		 * count of all channels.
 		 */
 		es58x_increment_rx_errors(es58x_dev);
 	}

  resubmit_urb:
+	usb_anchor_urb(urb, &es58x_dev->rx_urbs);
 	ret = usb_submit_urb(urb, GFP_ATOMIC);
+	if (!ret)
+		return;
+
+	usb_unanchor_urb(urb);
+
 	if (ret == -ENODEV) {
 		for (i = 0; i < es58x_dev->num_can_ch; i++)
 			if (es58x_dev->netdev[i])
 				netif_device_detach(es58x_dev->netdev[i]);
-	} else if (ret)
+	} else
 		dev_err_ratelimited(dev,
 				    "Failed resubmitting read bulk urb: %pe\n",
 				    ERR_PTR(ret));
 	return;

  free_urb:
 	usb_free_coherent(urb->dev, urb->transfer_buffer_length,
 			  urb->transfer_buffer, urb->transfer_dma);
 }



